function habitVersionDue(v,date){let day=new Date(date+'T12:00:00').getDay();if(v.frequency==='weekdays')return day>=1&&day<=5;if(v.frequency==='custom')return (v.days||[]).map(Number).includes(day);return true}
function habitStats(start,end){
 const versions=data.habitVersions||[],dates=[];for(let d=start;d<=end;d=shiftDate(d,1))dates.push(d);
 let total=0,done=0,byId={};
 for(const v of versions){const from=v.start||start,to=v.end||'9999-12-31';let row=byId[v.id]??={id:v.id,name:v.name,done:0,total:0};if(v.name)row.name=v.name;
  for(const d of dates){if(d<from||d>to||!habitVersionDue(v,d))continue;row.total++;total++;if(data.habitLogs?.[d]?.[v.id]?.done){row.done++;done++}}
 }
 return {total,done,rate:total?Math.round(done/total*100):0,items:Object.values(byId).filter(x=>x.total>0).sort((a,b)=>a.name.localeCompare(b.name))};
}
function habitPeriodBounds(date,kind){
 const d=new Date(date+'T12:00:00');
 if(kind==='week'){const start=weekStart(date);return {start,end:shiftDate(start,6)}}
 const start=isoDate(new Date(d.getFullYear(),d.getMonth(),1)),end=isoDate(new Date(d.getFullYear(),d.getMonth()+1,0));
 return {start,end};
}
function previousHabitPeriodStart(start,kind){
 if(kind==='week')return shiftDate(start,-7);
 const d=new Date(start+'T12:00:00');return isoDate(new Date(d.getFullYear(),d.getMonth()-1,1));
}
function habitPeriodStreak(kind){
 const now=today(),current=habitPeriodBounds(now,kind),partial=habitStats(current.start,current.end);
 const currentPassed=partial.total>0&&partial.rate>=80;
 let streak=currentPassed?1:0;
 let cursor=previousHabitPeriodStart(current.start,kind);
 // 진행 중인 주/월은 아직 80%를 채우지 못했더라도 이전 스트릭을 즉시 끊지 않습니다.
 if(!currentPassed&&current.end<now)return 0;
 for(let i=0;i<120;i++){
  const period=habitPeriodBounds(cursor,kind),stats=habitStats(period.start,period.end);
  if(!stats.total||stats.rate<80)break;
  streak++;cursor=previousHabitPeriodStart(period.start,kind);
 }
 return streak;
}
