function reportMetrics(start,end){
  const r=rangeDates(start,end);
  const strength=new Set(r.workouts.filter(w=>w.type!=='CARDIO').map(w=>w.date)).size;
  const cardio=new Set(r.workouts.filter(w=>w.type==='CARDIO').map(w=>w.date)).size;
    const dayTotals={};r.meals.forEach(m=>{let d=dayTotals[m.date]??={cal:0,p:0};d.cal+=+m.calories||0;d.p+=+m.protein||0});
  const logged=Object.values(dayTotals),avgCal=logged.length?logged.reduce((a,x)=>a+x.cal,0)/logged.length:0,avgProtein=logged.length?logged.reduce((a,x)=>a+x.p,0)/logged.length:0;
  const weights=r.weights.slice().sort((a,b)=>a.date.localeCompare(b.date)),weightChange=weights.length>1?weights.at(-1).weight-weights[0].weight:null;
  const active=new Set([...r.workouts.map(w=>w.date),...r.meals.map(m=>m.date)].filter(Boolean));
  let longest=0,run=0,previous=null;
  for(const date of [...active].sort()){run=previous&&shiftDate(previous,1)===date?run+1:1;longest=Math.max(longest,run);previous=date}
  const missionKeys=Object.keys(data.weeklyMissions||{}).filter(k=>k<=end&&shiftDate(k,6)>=start);
  const missionTotal=missionKeys.reduce((n,k)=>n+(data.weeklyMissions[k]||[]).length,0);
  const missionDone=missionKeys.reduce((n,k)=>n+Object.keys(data.weeklyMissionClaims?.[k]||{}).length,0);
  const habits=habitStats(start,end);return {strength,cardio,avgCal,avgProtein,weightChange,activeDays:active.size,longest,missionTotal,missionDone,habitDone:habits.done,habitTotal:habits.total,habitRate:habits.rate};
}
function reportComparison(id,current,previous,unit='',higherBetter=true,decimals=0){
 const el=$(id);if(current===null||previous===null||!Number.isFinite(current)||!Number.isFinite(previous)){el.className='report-compare report-neutral';el.textContent='이전 기록 없음';return}
 const diff=current-previous;if(Math.abs(diff)<0.000001){el.className='report-compare report-neutral';el.textContent='변화 없음';return}
 const positive=higherBetter?diff>0:diff<0,amount=decimals?Math.abs(diff).toFixed(decimals):String(Math.abs(Math.round(diff)));
 el.className='report-compare '+(positive?'report-positive':'report-negative');
 el.textContent=(diff>0?'▲ +':'▼ ')+amount+unit+' · 이전 기간 대비';
}
function reportGoalComparison(id,current,previous,target,unit=''){
 const el=$(id);if(!current||!previous){el.className='report-compare report-neutral';el.textContent='비교할 이전 기록 없음';return}
 const improvement=Math.abs(previous-target)-Math.abs(current-target);
 if(Math.abs(improvement)<0.000001){el.className='report-compare report-neutral';el.textContent='목표와의 거리 동일';return}
 el.className='report-compare '+(improvement>0?'report-positive':'report-negative');
 el.textContent=(improvement>0?'▲ 목표에 가까워짐 ':'▼ 목표에서 멀어짐 ')+Math.abs(Math.round(improvement))+unit;
}
function renderReport(){
 $('reportPrev').disabled=reportOffset<=-120;$('reportNext').disabled=reportOffset>=0;
 const isExercise=reportMode==='exercise',isAchievements=reportMode==='achievements';$('reportPeriodNav').classList.toggle('hidden',isExercise||isAchievements);$('reportExercisePicker').classList.toggle('hidden',!isExercise);$('reportSummary').classList.toggle('hidden',isExercise||isAchievements);$('reportExercisePanel').classList.toggle('hidden',!isExercise);$('reportAchievementsPanel').classList.toggle('hidden',!isAchievements);
 document.querySelectorAll('[data-report-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.reportMode===reportMode));
 if(isAchievements){renderAchievements();return}if(isExercise){renderExerciseChart();return}
 const {start,end}=reportRange();let prevStart,prevEnd;
 if(reportMode==='week'){prevStart=shiftDate(start,-7);prevEnd=shiftDate(end,-7)}
 else{const d=new Date(start+'T12:00:00'),p=new Date(d.getFullYear(),d.getMonth()-1,1),last=new Date(d.getFullYear(),d.getMonth(),0);prevStart=isoDate(p);prevEnd=isoDate(last)}
 const current=reportMetrics(start,end),previous=reportMetrics(prevStart,prevEnd);
 const label=reportMode==='week'?new Date(start+'T12:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric'})+' – '+new Date(end+'T12:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric'}):new Date(start+'T12:00:00').toLocaleDateString('ko-KR',{year:'numeric',month:'long'});
 $('reportPeriodLabel').textContent=label;
 $('reportWorkoutDays').textContent=current.strength+'회';$('reportCardioDays').textContent=current.cardio+'회';
 $('reportAvgCalories').textContent=Math.round(current.avgCal).toLocaleString('ko-KR')+' kcal';$('reportAvgProtein').textContent=Math.round(current.avgProtein)+' g';
 $('reportActiveDays').textContent=current.longest+'일';$('reportBestStreak').textContent=current.activeDays+'일';
 $('reportMissionCount').textContent=current.missionTotal?current.missionDone+' / '+current.missionTotal+'개':'기록 없음';$('reportHabitRate').textContent=current.habitRate+'%';$('reportHabitCount').textContent=current.habitDone+' / '+current.habitTotal+'회 완료';$('reportHabitCard').dataset.start=start;$('reportHabitCard').dataset.end=end;
 const weight=current.weightChange;
 $('reportWeightChange').textContent=weight===null?'—':(weight>0?'+':'')+weight.toFixed(1)+' kg';
 $('reportWeightChange').className=weight===null?'':Math.abs(weight)<0.000001?'report-neutral':weight<0?'report-positive':'report-negative';
 reportComparison('reportWorkoutCompare',current.strength,previous.strength,'회');
 reportComparison('reportCardioCompare',current.cardio,previous.cardio,'회');
 reportComparison('reportActiveCompare',current.longest,previous.longest,'일');
 reportComparison('reportMissionCompare',current.missionDone,previous.missionDone,'개');
 if(weight!==null&&previous.weightChange!==null)reportComparison('reportWeightCompare',weight,previous.weightChange,' kg',false,1);
 else{const el=$('reportWeightCompare');el.className='report-compare report-neutral';el.textContent='체중 기록이 더 필요해요'}
 const g=goal();
 reportGoalComparison('reportCaloriesCompare',current.avgCal,previous.avgCal,g.calories,' kcal');
 reportGoalComparison('reportProteinCompare',current.avgProtein,previous.avgProtein,g.protein,' g');
 const diff=(a,b,label)=>a===b?label+' 변화 없음':label+(a>b?' '+(a-b)+'회 증가':' '+(b-a)+'회 감소');
 $('reportNarrative').textContent='이번 기간에는 웨이트 '+current.strength+'회, 유산소 '+current.cardio+'회 운동했어요. 총 '+current.activeDays+'일 활동했고, 최장 연속 활동은 '+current.longest+'일이에요. 이전 '+(reportMode==='week'?'주':'월')+'과 비교하면 '+diff(current.strength,previous.strength,'웨이트')+', '+diff(current.cardio,previous.cardio,'유산소')+'예요.';
}
function renderCharacterPreview(){const stages=[{file:1,from:1,to:9},{file:2,from:10,to:19},{file:3,from:20,to:29},{file:4,from:30,to:39},{file:6,from:40,to:49},{file:5,from:50,to:59},{file:7,from:60,to:69},{file:8,from:70,to:79},{file:9,from:80,to:89},{file:10,from:90,to:9999}],lv=level(),current=stages.findIndex(s=>lv>=s.from&&lv<=s.to);$('characterPreviewStages').innerHTML=stages.map((s,i)=>'<div class="character-stage '+(i===current?'current':'')+' '+(i<current?'unlocked':'future')+'"><img src="./stage'+String(s.file).padStart(2,'0')+'_cutout.png" alt="Stage '+String(s.file).padStart(2,'0')+'"><strong>'+((s.to===9999?'LV. 90+':'LV. '+s.from+'–'+s.to))+'</strong><small>'+(i===current?'CURRENT STAGE':i<current?'PREVIOUS FORM':'FUTURE EVOLUTION')+'</small></div>').join('')}
function renderHome(){let lv=level();$('level').textContent=lv;renderRank();$('xpText').textContent=`${currentXP()} / 100 XP`;$('xpBar').style.width=`${currentXP()}%`;let stage=lv>=90?10:lv>=80?9:lv>=70?8:lv>=60?7:lv>=50?5:lv>=40?6:lv>=30?4:lv>=20?3:lv>=10?2:1;const stageFiles={1:'stage01_cutout.png',2:'stage02_cutout.png',3:'stage03_cutout.png',4:'stage04_cutout.png',5:'stage05_cutout.png',6:'stage06_cutout.png',7:'stage07_cutout.png',8:'stage08_cutout.png',9:'stage09_cutout.png',10:'stage10_cutout.png'};$('stageLabel').textContent=`STAGE ${String(stage).padStart(2,'0')}`;$('avatar').onerror=()=>$('avatar').src='./placeholder.svg';$('avatar').src='./'+stageFiles[stage];let ws=todayWorkouts(),ms=todayMeals(),types=[...new Set(ws.map(w=>w.type))],tot=ms.reduce((a,m)=>({cal:a.cal+m.calories,p:a.p+m.protein}),{cal:0,p:0});$('todayWorkoutTypes').innerHTML=types.length?`<span class="status-state completed">COMPLETED</span><span class="status-main">${types.join(' · ')}</span><small class="status-extra">${ws.length} SESSION${ws.length===1?'':'S'} LOGGED</small>`:`<span class="status-state pending">PENDING</span><span class="status-main">No session</span><small class="status-extra">Ready when you are</small>`;let g=goal();$('todayCalories').innerHTML='<span class="home-intake">'+Math.round(tot.cal)+'</span><small class="home-goal">/ '+Math.round(g.calories)+' kcal</small>';$('todayProtein').innerHTML='<span class="home-intake">'+Math.round(tot.p)+'</span><small class="home-goal">/ '+Math.round(g.protein)+' g</small>';$('quests').innerHTML=quests().map(q=>`<div class="quest ${q.ok?'done':''}"><div class="quest-mark">${q.ok?'🔥':'○'}</div><div class="quest-copy"><strong>${q.title}</strong><small>${q.desc}</small>${q.progress!==undefined?`<small class="quest-progress">${q.progress} / ${q.total} 완료</small>`:''}</div><span class="quest-reward">${q.ok?'완료':q.noBonus?'습관 보상 포함':'🔥 +'+q.xp+' XP'}</span></div>`).join('');renderWeight();renderActivityStreak();renderWeeklyMissions()}
function renderWeight(){let logs=data.weightLogs.slice().sort((a,b)=>a.date.localeCompare(b.date)),last=logs.at(-1),first=logs[0];$('latestWeight').textContent=last?last.weight.toFixed(1)+' kg':'-- kg';$('weightChange').textContent=logs.length>1?((last.weight-first.weight>0?'+':'')+(last.weight-first.weight).toFixed(1)+' kg overall'):'No data';let a=logs.slice(-12),chart=$('weightChart');if(!a.length)chart.innerHTML='<div class="empty">Add your first weight record.</div>';else if(a.length===1)chart.innerHTML=`<div class="single-point"><i></i><strong>${a[0].weight.toFixed(1)} kg</strong><small>${dateLabel(a[0].date)}</small></div>`;else{let vals=a.map(x=>x.weight),lo=Math.min(...vals),hi=Math.max(...vals),range=Math.max(1,hi-lo),W=600,H=190,p=22,pts=a.map((x,i)=>({x:p+i*(W-2*p)/(a.length-1),y:123-(x.weight-lo)/range*100,...x}));chart.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Weight trend"><line x1="${p}" y1="145" x2="${W-p}" y2="145" class="chart-axis"/><polyline points="${pts.map(x=>x.x+','+x.y).join(' ')}" class="weight-line"/>${pts.map(x=>`<circle cx="${x.x}" cy="${x.y}" r="5" class="weight-dot"><title>${x.date}: ${x.weight} kg</title></circle><text x="${x.x}" y="${Math.max(12,x.y-10)}" class="weight-value" text-anchor="middle">${x.weight.toFixed(1)}</text><text x="${x.x}" y="184" class="weight-date" text-anchor="middle">${x.date.slice(5).replace('-','/')}</text>`).join('')}</svg>`} $('weightHistory').textContent=logs.slice(-4).reverse().map(x=>dateLabel(x.date)+' · '+x.weight.toFixed(1)+' kg').join('   /   ');$('weightDetail').innerHTML=logs.slice().reverse().map(x=>`<div class="record"><div class="record-head"><strong>${x.weight.toFixed(1)} kg</strong><small>${dateLabel(x.date)}</small><button class="delete" data-delete-weight="${x.date}">DELETE</button></div></div>`).join('')||'<div class="empty-state">No weight records yet.</div>';renderWeightGoal()}

function addSet(w='',r=''){let n=$('sets').children.length+1,d=document.createElement('div');d.className='set-row';d.innerHTML=`<span>${n}</span><input type="number" min="0" step=".5" placeholder="KG" value="${w}"><input type="number" min="1" placeholder="REPS" value="${r}"><button type="button" class="remove-set">×</button>`;d.querySelector('button').onclick=()=>{d.remove();[...$('sets').children].forEach((x,i)=>x.firstElementChild.textContent=i+1)};$('sets').append(d)}
function previousExercise(type,name,date){let norm=s=>(s||'').trim().toLowerCase();for(let w of data.workouts.filter(x=>x.type===type&&x.date<date).sort((a,b)=>b.date.localeCompare(a.date))){let e=(w.exercises||[]).find(x=>norm(x.name)===norm(name));if(e?.sets?.length)return {w,e}}return null}
function exerciseMatches(query){let q=query.trim().toLowerCase();if(q.length<1)return [];let seen=new Map();for(let w of data.workouts.filter(x=>x.type===$('workoutType').value).sort((a,b)=>b.date.localeCompare(a.date))){for(let e of w.exercises||[]){let k=e.name.trim().toLowerCase();if(k.startsWith(q)&&!seen.has(k))seen.set(k,e.name)}}return [...seen.values()].slice(0,7)}
function renderExerciseSuggestions(){let box=$('exerciseSuggestions'),q=$('exercise').value.trim();if($('workoutType').value==='CARDIO'||!q){box.classList.add('hidden');box.innerHTML='';return}let names=exerciseMatches(q);box.innerHTML=names.map((name,i)=>`<button type="button" class="autocomplete-option" data-exercise-select="${i}">${name}</button>`).join('');box.classList.toggle('hidden',!names.length);box.dataset.names=JSON.stringify(names)}
function showRecommendation(){let box=$('recommendation'),type=$('workoutType').value,name=$('exercise').value.trim(),date=$('workoutDate').value||today(),prev=previousExercise(type,name,date);if(type==='CARDIO'||!name||$('exercise').dataset.selected!=='true'||!prev){box.classList.add('hidden');box.innerHTML='';return}let sets=prev.e.sets,allTen=sets.length>0&&sets.every(x=>(+x.reps||0)>=10),next=sets.map((x,i)=>{let reps=+x.reps||0,weight=+x.weight||0;if(allTen)return {weight:weight>0?weight+2.5:weight,reps:i===0?10:8};if(reps<8){let reduce=reps<=6&&weight>0;return {weight:Math.max(0,weight-(reduce?2.5:0)),reps:8}}return {weight,reps:reps+1}}),status=allTen?'WEIGHT UP':sets.some(x=>(+x.reps||0)<8)?'ADJUST LOAD':'BUILD REPS',note=allTen?'All sets reached 10+ reps. Increase each set by 2.5 kg and build reps again.':sets.some(x=>(+x.reps||0)<8)?'A set fell below 8 reps. Keep the load at 7 reps; reduce by 2.5 kg at 6 reps or fewer.':'Keep the load and aim for one more rep per set. SET 01 target: 10 reps; remaining sets: 8+ reps.',weights=next.map(x=>x.weight),minW=Math.min(...weights),maxW=Math.max(...weights),weightLabel=minW===maxW?minW+' KG':minW+'–'+maxW+' KG',repLabel=next.map(x=>x.reps).join(' / ');box.classList.remove('hidden');box.innerHTML=`<div class="recommendation-head"><div><span class="recommendation-kicker">NEXT SESSION</span><strong>PROGRESSION PLAN</strong></div><span class="recommendation-status ${allTen?'weight-up':status==='ADJUST LOAD'?'adjust-load':'build-reps'}">${status}</span></div><div class="recommendation-metrics"><div><span>WEIGHT</span><strong class="rec-weight">${weightLabel}</strong></div><div><span>REPS</span><strong class="rec-reps">${repLabel}</strong></div><div><span>SETS</span><strong class="rec-sets">${next.length}</strong></div></div><div class="recommendation-set-list">${next.map((x,i)=>`<div class="recommendation-set"><span>SET ${String(i+1).padStart(2,'0')}</span><strong><b>${x.weight} KG</b><i>×</i><em>${x.reps} REPS</em></strong></div>`).join('')}</div><p class="recommendation-note">${note}</p><button type="button" class="primary wide" id="useRecommendation">USE RECOMMENDATION</button><small class="recommendation-previous">PREVIOUS: ${dateLabel(prev.w.date)} · ${sets.map(x=>x.weight+'kg × '+x.reps).join(' / ')}</small>`;$('useRecommendation').onclick=()=>{$('sets').innerHTML='';next.forEach(x=>addSet(x.weight,x.reps))}}
function renderDraft(){$('draftExercises').innerHTML=draft.map((e,i)=>{let meta=e.sets.length?e.sets.map(s=>s.weight+'kg × '+s.reps).join(' · '):[e.minutes?'TIME '+e.minutes+'분':'',e.distance?'DISTANCE '+e.distance+'km':'',e.pace?'PACE '+formatPace(e.pace):'',e.rounds?'CIRCUIT '+e.rounds+'라운드':''].filter(Boolean).join(' · ')||'기록 없음';return `<div class="draft-item"><div><strong>${e.name}</strong><small>${meta}${e.dropSet?' · 777 DROP SET':''}</small></div><button class="delete" data-remove-draft="${i}">REMOVE</button></div>`}).join('');$('draftCount').textContent=draft.length+' EXERCISE'+(draft.length===1?'':'S')+' READY'}
function volume(w){return (w.exercises||[]).reduce((n,e)=>n+(e.sets||[]).reduce((s,x)=>s+(+x.weight||0)*(+x.reps||0),0),0)}
function activeDates(){return new Set([...data.workouts.map(w=>w.date),...data.meals.map(m=>m.date)].filter(Boolean))}
function renderActivityStreak(){let active=activeDates(),d=new Date();d.setHours(12,0,0,0);let key=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`,todayKey=key(d),streak=0,cursor=new Date(d);if(!active.has(todayKey))cursor.setDate(cursor.getDate()-1);while(active.has(key(cursor))){streak++;cursor.setDate(cursor.getDate()-1)}let dates=[...active].sort(),longest=0,run=0,prev=null;for(let k of dates){let x=new Date(k+'T12:00:00');if(prev){let p=new Date(prev+'T12:00:00');p.setDate(p.getDate()+1);run=key(p)===k?run+1:1}else run=1;longest=Math.max(longest,run);prev=k}let monday=new Date(d);monday.setDate(d.getDate()-(d.getDay()+6)%7);let days=['MON','TUE','WED','THU','FRI','SAT','SUN'],week=days.map((label,i)=>{let x=new Date(monday);x.setDate(monday.getDate()+i);let k=key(x),on=active.has(k),future=k>todayKey;return `<div class="streak-day ${on?'done':''} ${k===todayKey?'today':''}"><small>${label}</small><span>${on?'✓':future?'·':'—'}</span></div>`}),weekCount=days.reduce((n,_,i)=>{let x=new Date(monday);x.setDate(monday.getDate()+i);return n+(key(x)<=todayKey&&active.has(key(x))?1:0)},0);$('streakCount').textContent=streak;$('streakWeek').innerHTML=week.join('');$('streakWeekCount').textContent=weekCount+' / 7 DAYS';$('streakLongest').textContent=longest+' DAYS'}
function liftKey(name){let n=(name||'').toLowerCase().replace(/[\\s_-]/g,'');if(['benchpress','barbellbenchpress','bench','벤치프레스','벤치'].includes(n))return 'bench';if(['squat','backsquat','barbellbacksquat','스쿼트'].includes(n))return 'squat';if(['deadlift','conventionaldeadlift','바벨데드리프트','데드리프트'].includes(n))return 'deadlift';return null}
function renderExerciseGrowth(){let defs=[{key:'squat',name:'SQUAT'},{key:'bench',name:'BENCH PRESS'},{key:'deadlift',name:'DEADLIFT'}],best={};for(let w of data.workouts){for(let e of w.exercises||[]){let key=liftKey(e.name);if(!key||!e.sets?.length)continue;for(let s of e.sets){let weight=+s.weight||0,reps=+s.reps||0;if(weight<=0||reps<=0)continue;let old=best[key];if(!old||weight>old.weight||(weight===old.weight&&reps>old.reps))best[key]={weight,reps,oneRM:weight*(1+reps/30),date:w.date}}}}let total=defs.reduce((n,x)=>n+(best[x.key]?.weight||0),0),estimatedTotal=defs.reduce((n,x)=>n+(best[x.key]?.oneRM||0),0);$('exerciseGrowth').innerHTML=`<article class="total-strength"><small>3-LIFT TOTAL · ACTUAL BEST WEIGHTS</small><strong>${total.toLocaleString()} <i>KG</i></strong><span>BEST RECORDED WEIGHT · SQUAT + BENCH + DEADLIFT</span><div class="total-estimated"><small>ESTIMATED 1RM TOTAL</small><strong>${estimatedTotal.toFixed(1)} <i>KG</i></strong><span>SUM OF EACH LIFT'S BEST ESTIMATED 1RM</span></div></article>`+defs.map(x=>{let r=best[x.key];return `<article class="growth-card lift-card"><div class="growth-title"><strong>${x.name}</strong><span>${r?'RECORDED':'NO RECORD'}</span></div><div class="lift-main">${r?`${r.weight} <small>KG × ${r.reps} REPS</small>`:'—'}</div><div class="lift-estimate"><span>ESTIMATED 1RM</span><strong>${r?r.oneRM.toFixed(1)+' kg':'—'}</strong></div></article>`}).join('')}function renderCalendar(){let y=calMonth.getFullYear(),m=calMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),map={};data.workouts.forEach(w=>(map[w.date]??=[]).push(w.type));$('calendarTitle').textContent=calMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'});let cells=Array(first).fill('<span class="calendar-blank"></span>');for(let d=1;d<=days;d++){let date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,types=[...new Set(map[date]||[])];cells.push(`<button type="button" class="calendar-day ${date===($('workoutHistoryDate').value||today())?'selected':''} ${date===today()?'today':''}" data-calendar-date="${date}"><span>${d}</span><i class="calendar-dots">${types.map(t=>`<b style="background:${COLORS[t]}" title="${t}"></b>`).join('')}</i></button>`)}$('calendarGrid').innerHTML=cells.join('')}
function renderHistory(){let date=$('workoutHistoryDate').value||today(),rows=data.workouts.filter(w=>w.date===date).sort((a,b)=>a.type.localeCompare(b.type));$('workoutDate').value=date;$('workoutHistory').innerHTML=rows.map(w=>`<article class="record workout-record" data-open-record="${w.id}"><div class="record-head"><div><strong><i class="type-dot" style="background:${COLORS[w.type]}"></i>${w.type}</strong><small>${w.exercises.length} exercises · ${dateLabel(w.date)}</small></div><span class="record-volume">${volume(w).toLocaleString()} kg</span></div><div class="record-meta">${w.exercises.map(e=>e.name).join(' · ')}</div><small class="tap-hint">TAP TO VIEW DETAILS</small></article>`).join('')||'<div class="empty-state">No workout records for this date.</div>';renderCalendar();renderExerciseGrowth()}
function formatPace(value){let seconds=Math.round((+value||0)*60);return Math.floor(seconds/60)+"'"+String(seconds%60).padStart(2,'0')+'"/km'}function showDetails(id){let w=data.workouts.find(x=>x.id===id);if(!w)return;$('workoutDetailTitle').textContent=w.type+' · '+dateLabel(w.date);$('workoutDetailBody').innerHTML=w.exercises.map(e=>'<article class="detail-exercise"><strong>'+escapeHabit(e.name)+'</strong>'+(e.dropSet?'<span class="drop-set-tag">777 DROP SET COMPLETED</span>':'')+(e.sets?.length?'<div class="set-table"><div class="set-table-head"><span>SET</span><span>WEIGHT</span><span>REPS</span><span>VOLUME</span></div>'+e.sets.map((s,i)=>'<div class="set-table-row"><span>'+(i+1)+'</span><span>'+s.weight+' kg</span><span>'+s.reps+'</span><span>'+(s.weight*s.reps).toLocaleString()+' kg</span></div>').join('')+'</div>':'<p class="record-meta">'+((e.minutes?'TIME '+e.minutes+'분':'')+(e.distance?(e.minutes?' · ':'')+'DISTANCE '+e.distance+'km':'')+(e.pace?(e.minutes&&e.distance?' · ':'')+'평균 페이스 '+formatPace(e.pace):'')+(e.rounds?((e.minutes||e.distance)?' · ':'')+'CIRCUIT '+e.rounds+'라운드':'')||'CARDIO 기록')+'</p>')+'</article>').join('');$('workoutTotalVolume').textContent=volume(w).toLocaleString()+' kg total volume';$('deleteWorkoutRecord').dataset.deleteWorkout=w.id;$('workoutDetailDialog').showModal()}
function foodLibrary(){let map=new Map();for(const f of data.foods||[]){if(f.name)map.set(f.name.trim().toLowerCase(),f)}for(let m of data.meals.slice().reverse().sort((a,b)=>(b.date||'').localeCompare(a.date||''))){let k=(m.name||'').trim().toLowerCase();if(k&&!map.has(k))map.set(k,{name:m.name,calories:+m.calories||0,carbs:+m.carbs||0,protein:+m.protein||0,fat:+m.fat||0,baseAmount:1,unit:'회',legacy:true})}return [...map.values()]}
function foodMatches(query){let q=query.trim().toLowerCase();if(q.length<1)return [];return foodLibrary().filter(m=>m.name.toLowerCase().startsWith(q)).slice(0,7)}
function setMealMacros(n,food,quantity){let ratio=(+quantity||0)/(+food.baseAmount||1);$('mealCal'+n).value=((+food.calories||0)*ratio).toFixed(1);$('mealCarb'+n).value=((+food.carbs||0)*ratio).toFixed(1);$('mealPro'+n).value=((+food.protein||0)*ratio).toFixed(1);$('mealFat'+n).value=((+food.fat||0)*ratio).toFixed(1)}
function updateMealCalculated(n){let b=currentMealBase(n),q=+$('mealQuantity'+n).value||0,r=q/(b.baseAmount||1);$('mealCalculated'+n).textContent='섭취량 '+q+' '+b.unit+' · '+((b.calories*r)||0).toFixed(1)+' kcal · C '+((b.carbs*r)||0).toFixed(1)+'g · P '+((b.protein*r)||0).toFixed(1)+'g · F '+((b.fat*r)||0).toFixed(1)+'g'}
function currentMealBase(n){return {name:$('mealName'+n).value.trim(),calories:+$('mealBaseCal'+n).value||0,carbs:+$('mealBaseCarb'+n).value||0,protein:+$('mealBasePro'+n).value||0,fat:+$('mealBaseFat'+n).value||0,baseAmount:+$('mealBaseAmount'+n).value||1,unit:$('mealUnit'+n).value.trim()||'g'}}
function renderFoodSuggestions(n){let input=$('mealName'+n),box=$('foodSuggestions'+n),matches=foodMatches(input.value);box.innerHTML=matches.map((m,i)=>`<button type="button" class="autocomplete-option food-option" data-food-select="${n}:${i}"><strong>${escapeDietText(m.name)}</strong><small>${m.baseAmount||1}${escapeDietText(m.unit||'회')} 기준 · ${Math.round(m.calories)} kcal</small></button>`).join('');box.classList.toggle('hidden',!matches.length);box.dataset.names=JSON.stringify(matches.map(m=>m.name))}
function renderDiet(){let ms=todayMeals(),g=goal(),t=targetGrams(),tot=ms.reduce((a,m)=>({cal:a.cal+m.calories,c:a.c+m.carbs,p:a.p+m.protein,f:a.f+m.fat}),{cal:0,c:0,p:0,f:0});$('caloriesNow').textContent=Math.round(tot.cal);$('caloriesGoal').textContent=g.calories;$('caloriePct').textContent=Math.round(tot.cal/g.calories*100)+'%';$('calorieBar').style.width=Math.min(100,tot.cal/g.calories*100)+'%';$('calorieRing').style.setProperty('--p',Math.min(100,tot.cal/g.calories*100)+'%');[['carbs',tot.c,t.carbs],['protein',tot.p,t.protein],['fat',tot.f,t.fat]].forEach(([k,v,z])=>{$(k+'Now').textContent=Math.round(v)+'g';$(k+'Goal').textContent='/ '+z.toFixed(1)+'g';let remaining=z-v;$(k+'Remaining').textContent=z>0?(remaining>=0?'남음 '+remaining.toFixed(1)+'g':'초과 '+Math.abs(remaining).toFixed(1)+'g'):'목표 미설정';$(k+'Bar').style.width=Math.min(100,z?100*v/z:0)+'%'});$('mealCards').innerHTML=[1,2,3,4,5].map(n=>{let entries=ms.filter(m=>m.meal===n),sum=entries.reduce((a,m)=>({cal:a.cal+(+m.calories||0),c:a.c+(+m.carbs||0),p:a.p+(+m.protein||0),f:a.f+(+m.fat||0)}),{cal:0,c:0,p:0,f:0});return `<article class="meal-card"><button class="meal-toggle" data-meal-toggle="${n}"><div class="meal-heading"><strong>MEAL ${String(n).padStart(2,'0')}</strong><small>${entries.length?entries.map(m=>m.name).join(', '):'No meal logged yet'}</small><div class="meal-summary"><strong>${entries.length?Math.round(sum.cal)+' kcal':'— kcal'}</strong><span class="macro-carbs">C ${Math.round(sum.c)}g</span><span class="macro-protein">P ${Math.round(sum.p)}g</span><span class="macro-fat">F ${Math.round(sum.f)}g</span></div></div><span class="chevron">＋</span></button><div class="meal-content hidden" id="mealContent${n}"><label class="field-label">FOOD NAME<input id="mealName${n}" autocomplete="off" placeholder="What did you eat?"></label><div id="foodSuggestions${n}" class="autocomplete-list food-suggestions hidden"></div><div class="food-quantity-grid"><label class="field-label">기준량<input id="mealBaseAmount${n}" type="number" min=".01" step=".01" value="100"></label><label class="field-label">기준 단위<input id="mealUnit${n}" type="text" value="g" maxlength="12" placeholder="g / 개 / 캔"></label><label class="field-label">먹은 양<input id="mealQuantity${n}" type="number" min="0" step=".01" value="100"></label></div><p class="food-unit-hint">아래 영양성분은 위 기준량에 해당하는 값이에요.</p><div class="meal-macros"><label class="field-label">KCAL<input id="mealBaseCal${n}" type="number" min="0" step=".1" placeholder="0"></label><label class="field-label macro-carbs">CARBS<input id="mealBaseCarb${n}" type="number" min="0" step=".1" placeholder="g"></label><label class="field-label macro-protein">PROTEIN<input id="mealBasePro${n}" type="number" min="0" step=".1" placeholder="g"></label><label class="field-label macro-fat">FAT<input id="mealBaseFat${n}" type="number" min="0" step=".1" placeholder="g"></label></div><div class="food-calculated" id="mealCalculated${n}">섭취량 기준 영양성분이 자동 계산돼요.</div><button class="primary wide" data-save-meal="${n}">SAVE MEAL +10 XP</button><div class="meal-entries">${entries.map(m=>`<div class="meal-entry"><div><strong>${m.name}</strong><br><span>${m.calories} kcal · C ${m.carbs} / P ${m.protein} / F ${m.fat}g</span></div><button class="delete" data-delete-meal="${m.id}">×</button></div>`).join('')}</div></div></article>`}).join('');renderDietCalendar();renderDietHistory();}
function renderDietCalendar(){let y=dietCalMonth.getFullYear(),m=dietCalMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate(),logged=new Set(data.meals.map(x=>x.date));$('dietCalendarTitle').textContent=dietCalMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'});let cells=Array(first).fill('<span class="calendar-blank"></span>');for(let d=1;d<=days;d++){let date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,has=logged.has(date);cells.push(`<button type="button" class="calendar-day diet-calendar-day ${date===dietHistoryDate?'selected':''} ${date===today()?'today':''} ${has?'has-diet':''}" data-diet-date="${date}" aria-label="${date}${has?' 식단 기록 있음':''}"><span>${d}</span><i class="calendar-dots">${has?'<b></b>':''}</i></button>`)}$('dietCalendarGrid').innerHTML=cells.join('');$('dietCalendarPrev').disabled=y===2000&&m===0;$('dietCalendarNext').disabled=y===new Date().getFullYear()&&m===new Date().getMonth()}
function renderDietHistory(){let date=dietHistoryDate,rows=data.meals.filter(x=>x.date===date).slice().sort((a,b)=>(+a.meal||0)-(+b.meal||0));$('dietHistoryTitle').textContent=new Date(date+'T12:00:00').toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric'})+' 식단';$('dietHistoryCount').textContent=rows.length?rows.length+'개 기록':'기록 없음';let groups=[1,2,3,4,5].map(n=>({meal:n,items:rows.filter(m=>(+m.meal||0)===n)})).filter(g=>g.items.length);$('dietHistoryRecords').innerHTML=groups.length?groups.map(g=>{let total=g.items.reduce((sum,m)=>sum+(+m.calories||0),0);return `<article class="meal-card diet-history-meal-group"><div class="meal-toggle diet-history-meal-heading"><div class="meal-heading"><strong>MEAL ${String(g.meal).padStart(2,'0')}</strong><small>${g.items.length}개 메뉴 · ${Math.round(total)} kcal</small></div></div><div class="meal-content diet-history-meal-foods"><div class="meal-entries">${g.items.map(m=>`<div class="meal-entry"><div><strong>${escapeDietText(m.name)}</strong><br><span>${Math.round(+m.calories||0)} kcal · C ${(+m.carbs||0).toFixed(1)}g / P ${(+m.protein||0).toFixed(1)}g / F ${(+m.fat||0).toFixed(1)}g</span></div></div>`).join('')}</div></div></article>`}).join(''):'<div class="empty diet-history-empty">이 날짜에는 저장된 식단 기록이 없습니다.</div>'}
function escapeDietText(value){return String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}


function escapeHabit(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function habitDue(h,date=today()){let day=new Date(date+'T12:00:00').getDay();if(h.frequency==='weekdays')return day>=1&&day<=5;if(h.frequency==='custom')return (h.days||[]).map(Number).includes(day);return true}
function habitSchedule(h){return h.frequency==='weekdays'?'평일':h.frequency==='custom'?(h.days||[]).map(Number).sort((a,b)=>[1,2,3,4,5,6,0].indexOf(a)-[1,2,3,4,5,6,0].indexOf(b)).map(x=>['일','월','화','수','목','금','토'][x]).join(' · '):'매일'}
function ensureHabitVersions(){data.habitVersions??=[];for(const h of data.habits||[]){if(data.habitVersions.some(v=>v.id===h.id&&!v.end))continue;const logs=Object.keys(data.habitLogs||{}).filter(d=>data.habitLogs[d]?.[h.id]).sort();data.habitVersions.push({...h,start:h.createdAt||logs[0]||today(),end:null})}}
function renderHabits(){data.habits??=[];data.habitLogs??={};ensureHabitVersions();let day=today(),logs=data.habitLogs[day]||{},due=data.habits.filter(h=>habitDue(h)),done=due.filter(h=>logs[h.id]?.done).length;$('habitTodayCount').textContent=done+' / '+due.length+' 완료';$('habitCompletionRate').textContent=(due.length?Math.round(done/due.length*100):0)+'%';$('habitRewardTotal').textContent=(Object.values(data.habitLogs).reduce((n,dayLog)=>n+Object.values(dayLog||{}).filter(x=>x.done).length*5,0))+' EXP';$('habitWeeklyStreak').textContent=habitPeriodStreak('week')+'주';$('habitMonthlyStreak').textContent=habitPeriodStreak('month')+'개월';$('habitList').innerHTML=data.habits.map(h=>{let log=logs[h.id],dueToday=habitDue(h),input=h.targetType==='checkbox'?'':('<input class="habit-value" data-habit-value="'+h.id+'" type="number" min="0" step=".1" placeholder="'+(h.targetValue||1)+' '+escapeHabit(h.unit||'')+'" value="'+(log?.value??'')+'">');return '<article class="habit-card '+(log?.done?'done':'')+(!dueToday?' not-due':'')+'"><div class="habit-card-main"><div class="habit-icon">'+escapeHabit(h.icon||'✦')+'</div><div class="habit-copy"><strong>'+escapeHabit(h.name)+'</strong><small>'+escapeHabit(habitSchedule(h))+' · '+(dueToday?(h.targetType==='checkbox'?'완료 체크':('목표 '+h.targetValue+' '+escapeHabit(h.unit||''))):'오늘은 쉬는 날')+'</small></div><button class="habit-edit" data-habit-edit="'+h.id+'" aria-label="습관 수정">···</button></div><div class="habit-card-action">'+(dueToday?(input+(log?.done?'<span class="habit-done-label">완료 ✓</span>':'<button class="primary habit-complete" data-habit-complete="'+h.id+'">완료하기</button>')):'<span class="habit-rest-label">설정한 요일에 다시 표시돼요</span>')+'</div></article>'}).join('')||'<div class="empty-state">아직 등록한 습관이 없어요. 작은 습관부터 추가해 보세요.</div>';let history=Object.entries(data.habitLogs).sort((a,b)=>b[0].localeCompare(a[0])).slice(0,7);$('habitHistory').innerHTML=history.map(([date,items])=>'<div class="habit-history-row"><strong>'+date+'</strong><span>'+Object.values(items||{}).filter(x=>x.done).length+'개 완료</span></div>').join('')||'<div class="empty-state">습관을 완료하면 기록이 여기에 쌓여요.</div>'}
function openHabitEditor(h){$('habitId').value=h?.id||'';$('habitName').value=h?.name||'';$('habitIcon').value=h?.icon||'✦';$('habitFrequency').value=h?.frequency||'daily';$('habitTargetType').value=h?.targetType||'checkbox';$('habitTargetValue').value=h?.targetValue||1;$('habitUnit').value=h?.unit||'회';document.querySelectorAll('#habitWeekdayPicker input').forEach(x=>x.checked=(h?.days||[]).map(Number).includes(+x.value));$('habitWeekdayPicker').classList.toggle('hidden',$('habitFrequency').value!=='custom');$('habitTargetFields').classList.toggle('hidden',$('habitTargetType').value==='checkbox');$('habitEditorTitle').textContent=h?'습관 수정':'습관 만들기';$('deleteHabit').classList.toggle('hidden',!h);$('deleteHabit').dataset.deleteHabit=h?.id||'';$('habitEditorDialog').showModal()}
async function completeHabit(id){let h=data.habits.find(x=>x.id===id);if(!h)return;data.habitLogs??={};data.habitLogs[today()]??={};if(data.habitLogs[today()][id]?.done)return;let value=true;if(h.targetType!=='checkbox'){let el=document.querySelector('[data-habit-value="'+id+'"]');value=+(el?.value||0);if(value<(+h.targetValue||1))return alert('목표 수치를 채워 주세요.');}data.habitLogs[today()][id]={done:true,value};grantXP(5);data.coins=(+data.coins||0)+2;await writeSave();showXPGain(5,'습관 완료 · 코인 +2');renderHabits();renderHome()}
$('addHabit').onclick=()=>openHabitEditor();$('closeHabitEditor').onclick=()=>$('habitEditorDialog').close();$('deleteHabit').onclick=async()=>{let id=$('deleteHabit').dataset.deleteHabit;if(!id)return;if(!confirm('이 습관을 삭제할까요? 기존 달성 기록은 보존됩니다.'))return;data.habitVersions??=[];let activeVersion=data.habitVersions.find(v=>v.id===id&&!v.end);if(activeVersion)activeVersion.end=today();data.habits=data.habits.filter(h=>h.id!==id);await writeSave();$('habitEditorDialog').close();renderHabits()};$('habitFrequency').onchange=()=> $('habitWeekdayPicker').classList.toggle('hidden',$('habitFrequency').value!=='custom');$('habitTargetType').onchange=()=> $('habitTargetFields').classList.toggle('hidden',$('habitTargetType').value==='checkbox');
$('habitForm').onsubmit=async e=>{e.preventDefault();let id=$('habitId').value,name=$('habitName').value.trim(),frequency=$('habitFrequency').value,targetType=$('habitTargetType').value,days=[...document.querySelectorAll('#habitWeekdayPicker input:checked')].map(x=>+x.value);if(!name)return;if(frequency==='custom'&&!days.length)return alert('반복할 요일을 하나 이상 선택해 주세요.');let item={id:id||uid(),name,icon:$('habitIcon').value.trim()||'✦',frequency,days,targetType,targetValue:targetType==='checkbox'?1:(+$('habitTargetValue').value||1),unit:$('habitUnit').value.trim()||'회'};let i=data.habits.findIndex(x=>x.id===item.id);data.habitVersions??=[];if(i>=0){let activeVersion=data.habitVersions.find(v=>v.id===item.id&&!v.end);if(activeVersion)activeVersion.end=today();data.habits[i]=item;data.habitVersions.push({...item,start:shiftDate(today(),1),end:null})}else{item.createdAt=today();data.habits.push(item);data.habitVersions.push({...item,start:today(),end:null})}await writeSave();$('habitEditorDialog').close();renderHabits();renderHome()};
